def add(paper, text):
    rows = []
    for line in text.strip().splitlines():
        cells = line.split('|')
        assert len(cells) == 8, (paper, len(cells), line)
        num, status, summary, location, verification, routes, mechanism, implement = cells
        rows.append(dict(issue_id='llm_issue_' + num, status=status, summary=summary,
                         location=location, verification=verification,
                         routes=routes.split('；另一路：'), mechanism=mechanism,
                         implement=implement))
    ANALYSES[paper] = rows

