def load_rows(name):
    return [json.loads(line) for line in (BASE / name).read_text(encoding='utf-8').splitlines() if line.strip()]

def fmt_date(ms):
    return datetime.datetime.fromtimestamp(ms / 1000, datetime.timezone(datetime.timedelta(hours=8))).isoformat(timespec='seconds') if ms else '未提供'

def link(path, label=None):
    return f'[{label or path.name}]({path.resolve().as_posix()})'

def main():
    import fitz
    coverage = {r['issue_id']: r for r in load_rows('reviewer_concerns_covered.jsonl')}
    missed = {}
    for name in ['J1', 'J2', 'J3']:
        for row in load_rows(f'reviewer_concerns_{name}.jsonl'):
            assert row['covered'] is False
            assert row['manual_judgment_path'] == name
            assert row['issue_id'] not in missed
            missed[row['issue_id']] = row
    manifest, audits, counts = [], [], []
    for number in ['003', '063', '143', '175']:
        source_rows = json.loads((BASE / f'{number}_concerns_source.json').read_text(encoding='utf-8'))
        annotations = {r['issue_id']: r for r in ANALYSES[number]}
        assert len(annotations) == len(ANALYSES[number])
        assert set(annotations) == {r['issue_id'] for r in source_rows}, number
        review_file = next((GOLDEN / 'data/human_testset').glob(number + '_*.json'))
        raw = json.loads(review_file.read_text(encoding='utf-8'))
        pdf_file = next((GOLDEN / 'review_pdfs/human_testset').glob(number + '_*.pdf'))
        parsed_file = next((GOLDEN / 'pdf_content').glob(number + '_*.json'))
        doc = fitz.open(pdf_file)
        sha = hashlib.sha256(pdf_file.read_bytes()).hexdigest()
        stats = collections.Counter(str(r['covered']) for r in source_rows)
        status_stats = collections.Counter(a['status'] for a in annotations.values())
        manifest.append(dict(paper=number, paper_url=raw['paper_url'], pdf_file=str(pdf_file),
                             sha256=sha, pages=len(doc), metadata=doc.metadata,
                             reviews=[dict(review_id=r['review_id'], cdate=r.get('cdate'), mdate=r.get('mdate')) for r in raw['reviews']],
                             counts=dict(stats), annotation_counts=dict(status_stats)))
        counts.append((number, len(source_rows), stats['True'], stats['False'], stats['None']))
        report = [f'# {number}｜{raw["paper_title"]}', '',
                  '## 核验基准与边界', '',
                  '本报告以用户指定的本地 **PDF** 为原文基准；`pdf_content` JSON只用于辅助理解结构，不用于推翻PDF。PDF页码为从1起的文件页序。逐条保留官方意见、issue ID和覆盖标签，错误分句在规律总结中排除，但不销毁历史记录。', '',
                  f'- 原文：{link(pdf_file)}（{len(doc)}页）。',
                  f'- `paper_url`：{raw["paper_url"]}。',
                  f'- PDF SHA256：`{sha}`。',
                  f'- 官方评审：{link(review_file)}；拆解输入：{link(BASE / (number + "_concerns_source.json"))}。',
                  f'- PDF直接提取的检索文本：{link(BASE / (number + "_pdf_text.txt"))}；该文本会丢失公式和布局，视觉意见另核页面。',
                  f'- 原输入{len(source_rows)}条：covered=true {stats["True"]}；false {stats["False"]}；null {stats["None"]}。', '',
                  '**判定约定**：保留=有PDF支持；部分保留/部分排除=拆掉不成立的绝对词或分句再保留剩余；评价/建议保留=可辩护的意见，不冒充事实错误；待核实=证据不够；当前排除/历史待核与版本待核=不纳入本版确定缺陷。版本差异不能证明审稿人当时说错。', '',
                  '**思考路线是研究者推断，不是审稿人的真实心理记录。** 下文列出相近的备选路线，不分配伪精确概率。漏召回说明依据现有覆盖映射和问题结构，属于机制假说；没有这次triage完整候选、检索上下文、过滤阈值和日志，不能确认失败发生在哪一步。`related_concern_ids`是关联，并不等于实际已召回；false条目都有关联但coverage IDs为空，不能据关联ID宣称已被检测。', '',
                  '**范围**：119条拆解输入逐条全部审计；又检查原始official review中未被该输入收录的实质意见，作为补充项列出，覆盖状态unknown。strengths用于解释同一评审上下文而不计concern；不做最终裁决影响分析。', '',
                  '## 本篇发现与可实现路线', '', SYNOPSES[number], '',
                  '## 完整逐条核验、阅读路线与漏召回机制', '']
        for idx, row in enumerate(source_rows, 1):
            a = annotations[row['issue_id']]
            enriched = coverage.get(row['issue_id'], missed.get(row['issue_id'], row))
            assert (row['covered'] is not False) or row['issue_id'] in missed
            assert (row['covered'] is not True) or row['issue_id'] in coverage
            official_review = next(r for r in raw['reviews'] if r['review_id'] == row['review_id'])
            quoted = str(row['evidence']).replace('\n', '\n> ')
            # Verify the concern excerpt belongs to the corresponding raw review,
            # tolerating typography and hyphen variation without altering meaning.
            def norm(s):
                return re.sub(r'[^\w]', '', s.casefold(), flags=re.UNICODE)
            raw_text = '\n'.join(str(value) for value in official_review['content'].values())
            exact_source = norm(row['evidence']) in norm(raw_text)
            report.extend([f'### {idx:02d}. {row["issue_id"]}｜{a["summary"]}', '',
                           f'**原标签**：covered=`{str(row["covered"]).lower()}`；{row["manual_judgment_path"]}；{row["concern_type"]}。来源：[{row["review_id"]}]({row["review_url"]})，`{row["raw_source_field"]}`。', '',
                           f'> {quoted}', '',
                           f'**PDF核验：{a["status"]}。** {a["location"]}。{a["verification"]}', '',
                           '**可能阅读/思考路线**：', ''])
            for ridx, route in enumerate(a['routes'], 1):
                report.append(f'{ridx}. {route}')
            report.extend(['', f'**检测/漏召回判断**：{a["mechanism"]}'])
            if row['covered'] is False:
                report.append('原覆盖表明确为false，实际覆盖ID为空；没有完整运行轨迹，以下路径仅用于形成下轮诊断假说。')
                if a['status'] in ['当前排除/历史待核', '版本待核', '待核实']:
                    report.append('**本条不计入现PDF已核实缺陷的漏检规律**；可保留其历史问题类型作为待验证候选。')
                else:
                    report.append('本条保留的有效分句参与模式归纳；评价/建议只归入评价路径，不计作客观事实错误。')
            elif row['covered'] is None:
                report.append('覆盖状态未知，既不计命中，也不计漏召回。')
            else:
                actual = enriched.get('covered_by_triage_issues') or []
                dedup = list(dict.fromkeys(x['issue'] for x in actual))
                if dedup:
                    report.extend(['', '**已有覆盖映射的实际文本（保留完整映射供审阅）**：', ''])
                    report.extend('- ' + issue for issue in dedup)
                else:
                    report.append('该true条目没有`covered_by_triage_issues`具体文本，不能进一步验证匹配粒度。')
            report.extend(['', f'**可实现核查**：{a["implement"]}', ''])
            audits.append({'paper': number, **row, **a,
                           'source_excerpt_found_after_normalization': exact_source,
                           'related_concern_ids': enriched.get('related_concern_ids', []),
                           'coverage_concern_ids': enriched.get('coverage_concern_ids', []),
                           'covered_by_triage_issues': enriched.get('covered_by_triage_issues', []),
                           'interpretation': 'hypothesis_not_observed_thought_process',
                           'include_in_current_qualitative_patterns': a['status'] not in ['当前排除/历史待核', '版本待核', '待核实']})
        report.extend(['## 官方评审补充审计：输入未单列的意见', '',
                       '以下是人工核对原始评审后的补充，不赋造新的原issue ID，不重写原covered分母；同族项仅用于解释，不重复计数。', ''])
        for sid, review_id, field, summary, detail in SUPPLEMENTS[number]:
            if review_id == 'Nx_placeholder':
                review_id = 'KmQDfBE4jx'
            report.extend([f'### {number}-{sid}｜{summary}', '',
                           f'来源：[{review_id}](https://openreview.net/forum?id={raw["openreview_forum_id"]}&noteId={review_id})，`{field}`；covered=unknown。', '', detail, ''])
        report.extend(['## 外部资料与版本记录', '',
                       '外部资料仅用于核验推荐论文的时间和主题，不替代本地PDF。详见[版本与OpenReview链接审计](openreview_pdf_version_audit.md)及[跨篇总结](README.md)。', '',
                       '| Review ID | cdate（Asia/Shanghai） | mdate（Asia/Shanghai） |',
                       '|---|---|---|'])
        for r in raw['reviews']:
            report.append(f'| {r["review_id"]} | {fmt_date(r.get("cdate"))} | {fmt_date(r.get("mdate"))} |')
        report.extend(['', 'cdate是可见创建时点，mdate可能受状态/权限等变化影响；两者都不自动给出审稿人开始读稿时点，也不指定PDF版本。', ''])
        (BASE / f'{number}_report.md').write_text('\n'.join(report), encoding='utf-8')
    (BASE / 'audit_annotations.jsonl').write_text('\n'.join(json.dumps(r, ensure_ascii=False) for r in audits) + '\n', encoding='utf-8')
    (BASE / 'pdf_manifest.json').write_text(json.dumps(manifest, ensure_ascii=False, indent=2), encoding='utf-8')
    print(json.dumps(dict(counts=counts, annotations=len(audits),
                          source_excerpt_mismatches=[r['issue_id'] for r in audits if not r['source_excerpt_found_after_normalization']],
                          statuses={n: dict(collections.Counter(a['status'] for a in ANALYSES[n])) for n in ANALYSES}), ensure_ascii=False, indent=2))

if __name__ == '__main__':
    main()
